"""Textes de la Citadelle (suite) : les 13 fiches notions (enfant, grands, limite de l'image, idée fausse)."""
L = ["fr", "en", "es", "de", "it", "pt", "ru", "zh", "ja", "hi", "ar", "bn", "id", "ur"]


def T(*v):
    assert len(v) == 14, v[0]
    return dict(zip(L, v))


K = {
 # utilisateurs et groupes
 "cit.f.utilisateurs.enfant": T("Chaque habitant de l'ordinateur a un numéro et fait partie de clubs : les groupes.", "Every resident of the computer has a number and belongs to clubs: groups.", "Cada habitante del ordenador tiene un número y pertenece a clubes: los grupos.", "Jeder Bewohner des Computers hat eine Nummer und gehört zu Clubs: den Gruppen.", "Ogni abitante del computer ha un numero e fa parte di club: i gruppi.", "Cada morador do computador tem um número e faz parte de clubes: os grupos.", "У каждого жителя компьютера есть номер, и он состоит в клубах — группах.", "电脑里每个居民都有号码，还加入了俱乐部：也就是“组”。", "コンピュータの住人にはそれぞれ番号があり、クラブ（グループ）に入っている。", "कंप्यूटर के हर निवासी का एक नंबर होता है और वह क्लबों (समूहों) में होता है।", "لكل ساكن في الحاسوب رقم، وهو عضو في نوادٍ: المجموعات.", "কম্পিউটারের প্রত্যেক বাসিন্দার নম্বর আছে, আর সে ক্লাবে (গ্রুপে) থাকে।", "Setiap penghuni komputer punya nomor dan ikut klub: grup.", "کمپیوٹر کے ہر رہائشی کا نمبر ہوتا ہے اور وہ کلبوں (گروپوں) میں ہوتا ہے۔"),
 "cit.f.utilisateurs.grands": T("Un compte = un uid ; un groupe = un gid ; /etc/passwd et /etc/group les décrivent. chown change le propriétaire (root seulement).", "An account = a uid; a group = a gid; /etc/passwd and /etc/group describe them. chown changes the owner (root only).", "Una cuenta = un uid; un grupo = un gid; /etc/passwd y /etc/group los describen. chown cambia el propietario (solo root).", "Ein Konto = eine uid; eine Gruppe = eine gid; /etc/passwd und /etc/group beschreiben sie. chown ändert den Besitzer (nur root).", "Un account = un uid; un gruppo = un gid; /etc/passwd e /etc/group li descrivono. chown cambia il proprietario (solo root).", "Uma conta = um uid; um grupo = um gid; /etc/passwd e /etc/group os descrevem. chown muda o dono (só root).", "Учётная запись — uid; группа — gid; их описывают /etc/passwd и /etc/group. chown меняет владельца (только root).", "一个账号 = 一个 uid；一个组 = 一个 gid；由 /etc/passwd 和 /etc/group 描述。chown 改所有者（只有 root 能做）。", "アカウント＝uid、グループ＝gid。/etc/passwd と /etc/group に書かれている。chown は持ち主を変える（root だけ）。", "खाता = uid; समूह = gid; /etc/passwd और /etc/group इन्हें बताते हैं। chown मालिक बदलता है (सिर्फ़ root)।", "الحساب = uid؛ المجموعة = gid؛ يصفهما /etc/passwd و/etc/group. يغيّر chown المالك (root فقط).", "অ্যাকাউন্ট = uid; গ্রুপ = gid; /etc/passwd আর /etc/group এগুলো বর্ণনা করে। chown মালিক বদলায় (শুধু root)।", "Akun = uid; grup = gid; dijelaskan /etc/passwd dan /etc/group. chown mengganti pemilik (hanya root).", "اکاؤنٹ = uid؛ گروپ = gid؛ /etc/passwd اور /etc/group انہیں بیان کرتے ہیں۔ chown مالک بدلتا ہے (صرف root)۔"),
 "cit.f.utilisateurs.limite": T("Un « club » peut contenir des programmes, pas seulement des personnes (www-data, systemd…).", "A “club” can contain programs, not only people (www-data, systemd…).", "Un «club» puede contener programas, no solo personas (www-data, systemd…).", "Ein „Club“ kann Programme enthalten, nicht nur Menschen (www-data, systemd …).", "Un «club» può contenere programmi, non solo persone (www-data, systemd…).", "Um «clube» pode conter programas, não só pessoas (www-data, systemd…).", "В «клубе» могут быть программы, а не только люди (www-data, systemd…).", "“俱乐部”里也可能是程序，不只是人（www-data、systemd……）。", "「クラブ」には人だけでなくプログラムも入る（www-data、systemd など）。", "«क्लब» में लोग ही नहीं, प्रोग्राम भी हो सकते हैं (www-data, systemd…)।", "قد يضم «النادي» برامج لا أشخاصًا فقط (www-data، systemd…).", "«ক্লাবে» শুধু মানুষ নয়, প্রোগ্রামও থাকতে পারে (www-data, systemd…)।", "«Klub» bisa berisi program, bukan hanya orang (www-data, systemd…).", "«کلب» میں صرف لوگ نہیں، پروگرام بھی ہو سکتے ہیں (www-data، systemd…)۔"),
 "cit.f.utilisateurs.idee": T("« Être administrateur, c'est mieux pour tout faire » : faux, on travaille en compte normal et on ne demande les droits de root qu'au besoin.", "“Being admin is better for everything”: false, you work as a normal account and only ask for root rights when needed.", "«Ser administrador es mejor para todo»: falso, se trabaja con una cuenta normal y solo se piden derechos de root si hace falta.", "„Als Admin geht alles besser“: falsch, man arbeitet mit normalem Konto und holt root-Rechte nur bei Bedarf.", "«Essere amministratore è meglio per tutto»: falso, si lavora con un account normale e si chiedono i diritti di root solo se serve.", "«Ser administrador é melhor para tudo»: falso, trabalha-se com conta normal e só se pede root quando preciso.", "«Быть администратором удобнее во всём» — неверно: работают под обычной учётной записью и просят права root только при необходимости.", "“当管理员什么都方便”：错。平时用普通账号，只在需要时才申请 root 权限。", "「管理者のほうが何でもできて便利」：まちがい。ふだんはふつうのアカウントで、必要なときだけ root の権限をたのむ。", "«एडमिन रहना हर काम के लिए बेहतर»: गलत, आम खाते से काम करो और ज़रूरत पर ही root माँगो।", "«أن تكون مديرًا أفضل لكل شيء»: خطأ، نعمل بحساب عادي ولا نطلب صلاحيات root إلا عند الحاجة.", "«অ্যাডমিন হলে সব কাজে ভালো»: ভুল, সাধারণ অ্যাকাউন্টে কাজ করো, দরকারে শুধু root চাও।", "«Jadi admin lebih baik untuk semua hal»: salah, bekerjalah dengan akun biasa dan minta hak root hanya bila perlu.", "«ایڈمن ہونا ہر کام کے لیے بہتر»: غلط، عام اکاؤنٹ سے کام کرو اور ضرورت پر ہی root مانگو۔"),
 # umask
 "cit.f.umask.enfant": T("Le masque décide des cadenas des fichiers qui viennent de naître.", "The mask decides the locks of newborn files.", "La máscara decide los candados de los archivos recién nacidos.", "Die Maske bestimmt die Schlösser neugeborener Dateien.", "La maschera decide i lucchetti dei file appena nati.", "A máscara decide os cadeados dos arquivos recém-nascidos.", "Маска решает, какие замки будут у новорождённых файлов.", "面具决定刚出生的文件带什么锁。", "仮面は、生まれたてのファイルの錠前を決める。", "मुखौटा नई जन्मी फ़ाइलों के ताले तय करता है।", "القناع يقرر أقفال الملفات المولودة حديثًا.", "মুখোশ সদ্য জন্মানো ফাইলের তালা ঠিক করে।", "Topeng menentukan gembok berkas yang baru lahir.", "نقاب نئی پیدا ہونے والی فائلوں کے تالے طے کرتا ہے۔"),
 "cit.f.umask.grands": T("umask retire des bits aux droits par défaut (666 fichiers, 777 dossiers) : mode = défaut ET NON masque.", "umask removes bits from the default rights (666 files, 777 folders): mode = default AND NOT mask.", "umask quita bits a los permisos por defecto (666 archivos, 777 carpetas): modo = defecto Y NO máscara.", "umask entfernt Bits von den Standardrechten (666 Dateien, 777 Ordner): Modus = Standard UND NICHT Maske.", "umask toglie bit ai permessi predefiniti (666 file, 777 cartelle): modo = predefinito AND NOT maschera.", "umask tira bits das permissões padrão (666 arquivos, 777 pastas): modo = padrão E NÃO máscara.", "umask убирает биты из прав по умолчанию (666 файлы, 777 папки): режим = умолчание И НЕ маска.", "umask 从默认权限里去掉一些位（文件 666，文件夹 777）：模式 = 默认 与 非 掩码。", "umask は初期の権限から bit を取る（ファイル 666、フォルダ 777）：モード＝初期 AND NOT マスク。", "umask डिफ़ॉल्ट अधिकारों से बिट हटाता है (फ़ाइल 666, फ़ोल्डर 777): मोड = डिफ़ॉल्ट AND NOT मास्क।", "يزيل umask بتات من الصلاحيات الافتراضية (666 للملفات، 777 للمجلدات): الوضع = الافتراضي AND NOT القناع.", "umask ডিফল্ট অধিকার থেকে বিট সরায় (ফাইল 666, ফোল্ডার 777): মোড = ডিফল্ট AND NOT মাস্ক।", "umask mencabut bit dari hak bawaan (berkas 666, folder 777): mode = bawaan AND NOT topeng.", "umask ڈیفالٹ حقوق سے بٹ ہٹاتا ہے (فائل 666، فولڈر 777): موڈ = ڈیفالٹ AND NOT ماسک۔"),
 "cit.f.umask.limite": T("Le masque ne touche pas aux fichiers qui existent déjà ; il n'ajoute jamais de droit.", "The mask doesn't touch existing files; it never adds a right.", "La máscara no toca los archivos existentes; nunca añade un permiso.", "Die Maske ändert keine bestehenden Dateien; sie fügt nie ein Recht hinzu.", "La maschera non tocca i file esistenti; non aggiunge mai un diritto.", "A máscara não mexe nos arquivos existentes; nunca adiciona direito.", "Маска не трогает существующие файлы и никогда не добавляет прав.", "面具不会改已有的文件；它也从不加权限。", "仮面はもうあるファイルにはさわらない。権限を足すこともない。", "मुखौटा पहले से मौजूद फ़ाइलें नहीं छूता; यह कभी अधिकार नहीं जोड़ता।", "لا يمس القناع الملفات الموجودة؛ ولا يضيف حقًا أبدًا.", "মুখোশ আগে থেকে থাকা ফাইল ছোঁয় না; কখনো অধিকার যোগ করে না।", "Topeng tak menyentuh berkas yang sudah ada; tak pernah menambah hak.", "نقاب پہلے سے موجود فائلیں نہیں چھوتا؛ کبھی حق نہیں جوڑتا۔"),
 "cit.f.umask.idee": T("« umask 777 donne tous les droits » : faux, il les enlève tous.", "“umask 777 gives all rights”: false, it removes them all.", "«umask 777 da todos los permisos»: falso, los quita todos.", "„umask 777 gibt alle Rechte“: falsch, sie nimmt alle weg.", "«umask 777 dà tutti i diritti»: falso, li toglie tutti.", "«umask 777 dá todas as permissões»: falso, tira todas.", "«umask 777 даёт все права» — неверно, он их все убирает.", "“umask 777 给全部权限”：错，它把权限全拿掉了。", "「umask 777 は全部の権限をあたえる」：まちがい。全部取る。", "«umask 777 सारे अधिकार देता है»: गलत, यह सब हटा देता है।", "«umask 777 يعطي كل الحقوق»: خطأ، إنه يزيلها كلها.", "«umask 777 সব অধিকার দেয়»: ভুল, এটা সব সরিয়ে দেয়।", "«umask 777 memberi semua hak»: salah, ia mencabut semuanya.", "«umask 777 سارے حقوق دیتا ہے»: غلط، یہ سب ہٹا دیتا ہے۔"),
 # journaux
 "cit.f.journaux.enfant": T("Le registre du gardien note qui est venu, quand, et si ça a marché.", "The guard's register notes who came, when, and whether it worked.", "El registro del guardián anota quién vino, cuándo y si funcionó.", "Das Register des Wächters notiert, wer wann kam und ob es geklappt hat.", "Il registro del guardiano annota chi è venuto, quando e se ha funzionato.", "O registro do guardião anota quem veio, quando e se deu certo.", "Журнал стража записывает, кто приходил, когда и получилось ли.", "守卫的登记簿记下谁来了、什么时候来、成没成功。", "守り手の記録簿には、だれがいつ来て、うまくいったかが書かれる。", "पहरेदार का रजिस्टर लिखता है कौन आया, कब, और काम बना या नहीं।", "يسجّل سجل الحارس من جاء ومتى وهل نجح.", "পাহারাদারের খাতা লেখে কে এল, কখন, আর কাজ হল কি না।", "Buku penjaga mencatat siapa datang, kapan, dan berhasil atau tidak.", "پہرے دار کا رجسٹر لکھتا ہے کون آیا، کب، اور کام بنا یا نہیں۔"),
 "cit.f.journaux.grands": T("Les journaux (/var/log, journalctl) se lisent avec tail, grep, cut, sort | uniq -c : compter les échecs par adresse révèle une force brute.", "Logs (/var/log, journalctl) are read with tail, grep, cut, sort | uniq -c: counting failures per address reveals brute force.", "Los registros (/var/log, journalctl) se leen con tail, grep, cut, sort | uniq -c: contar fallos por dirección revela fuerza bruta.", "Protokolle (/var/log, journalctl) liest man mit tail, grep, cut, sort | uniq -c: Fehlschläge pro Adresse zählen entlarvt Brute Force.", "I registri (/var/log, journalctl) si leggono con tail, grep, cut, sort | uniq -c: contare i fallimenti per indirizzo rivela la forza bruta.", "Os registros (/var/log, journalctl) se leem com tail, grep, cut, sort | uniq -c: contar falhas por endereço revela força bruta.", "Журналы (/var/log, journalctl) читают через tail, grep, cut, sort | uniq -c: подсчёт неудач по адресам выдаёт перебор.", "日志（/var/log、journalctl）用 tail、grep、cut、sort | uniq -c 来读：按地址数失败次数，就能发现暴力破解。", "記録（/var/log、journalctl）は tail、grep、cut、sort | uniq -c で読む。アドレスごとに失敗を数えると総当たりが見つかる。", "लॉग (/var/log, journalctl) tail, grep, cut, sort | uniq -c से पढ़ते हैं: पते के हिसाब से नाकामियाँ गिनने से ब्रूट-फ़ोर्स पकड़ा जाता है।", "تُقرأ السجلات (/var/log، journalctl) بـ tail وgrep وcut وsort | uniq -c: عدّ الفشل لكل عنوان يكشف القوة الغاشمة.", "লগ (/var/log, journalctl) পড়া হয় tail, grep, cut, sort | uniq -c দিয়ে: ঠিকানা ধরে ব্যর্থতা গুনলে ব্রুট-ফোর্স ধরা পড়ে।", "Log (/var/log, journalctl) dibaca dengan tail, grep, cut, sort | uniq -c: menghitung kegagalan per alamat mengungkap brute force.", "لاگ (/var/log، journalctl) tail، grep، cut، sort | uniq -c سے پڑھتے ہیں: پتے کے حساب سے ناکامیاں گننے سے بروٹ فورس پکڑا جاتا ہے۔"),
 "cit.f.journaux.limite": T("Le registre du jeu est inventé ; un vrai journal a mille formats différents et peut être effacé par un intrus.", "The game's register is invented; real logs come in a thousand formats and can be erased by an intruder.", "El registro del juego es inventado; los reales tienen mil formatos y un intruso puede borrarlos.", "Das Register des Spiels ist erfunden; echte Protokolle haben tausend Formate und können von Eindringlingen gelöscht werden.", "Il registro del gioco è inventato; quelli veri hanno mille formati e un intruso può cancellarli.", "O registro do jogo é inventado; os reais têm mil formatos e podem ser apagados por um intruso.", "Журнал игры выдуман; настоящие бывают в тысяче форматов, и нарушитель может их стереть.", "游戏的登记簿是编的；真的日志格式千奇百怪，入侵者还可能把它删掉。", "ゲームの記録は作りもの。本物の記録は形式がいろいろで、侵入者に消されることもある。", "खेल का रजिस्टर काल्पनिक है; असली लॉग हज़ार ढंग के होते हैं और घुसपैठिया उन्हें मिटा सकता है।", "سجل اللعبة مخترع؛ والسجلات الحقيقية لها ألف صيغة وقد يمحوها الدخيل.", "খেলার খাতা বানানো; আসল লগ হাজার রকমের, আর অনুপ্রবেশকারী মুছে দিতে পারে।", "Buku permainan itu karangan; log sungguhan punya seribu format dan bisa dihapus penyusup.", "کھیل کا رجسٹر فرضی ہے؛ اصل لاگ ہزار طرح کے ہوتے ہیں اور گھس بیٹھیا انہیں مٹا سکتا ہے۔"),
 "cit.f.journaux.idee": T("« S'il n'y a rien dans les journaux, il ne s'est rien passé » : faux, on peut ne rien avoir noté ou tout avoir effacé.", "“If the logs are empty, nothing happened”: false, nothing may have been recorded, or everything erased.", "«Si no hay nada en los registros, no pasó nada»: falso, puede que no se anotara nada o que se borrara todo.", "„Steht nichts im Protokoll, ist nichts passiert“: falsch, vielleicht wurde nichts notiert oder alles gelöscht.", "«Se nei registri non c'è nulla, non è successo nulla»: falso, forse non si è annotato nulla o si è cancellato tutto.", "«Se não há nada nos registros, nada aconteceu»: falso, pode não ter sido anotado ou tudo ter sido apagado.", "«Если в журналах пусто, ничего не было» — неверно: могли ничего не записать или всё стереть.", "“日志里什么都没有，就是什么都没发生”：错，可能根本没记，或者全被删了。", "「記録に何もなければ何も起きていない」：まちがい。記録しなかったか、全部消されたのかもしれない。", "«लॉग में कुछ नहीं तो कुछ हुआ ही नहीं»: गलत, शायद कुछ लिखा ही न गया हो या सब मिटा दिया गया हो।", "«إذا لم يكن في السجلات شيء فلم يحدث شيء»: خطأ، ربما لم يُسجَّل شيء أو مُحي كل شيء.", "«লগে কিছু না থাকলে কিছুই হয়নি»: ভুল, হয়তো কিছু লেখা হয়নি বা সব মোছা হয়েছে।", "«Kalau log kosong, tak terjadi apa-apa»: salah, mungkin tak tercatat atau semuanya dihapus.", "«لاگ میں کچھ نہیں تو کچھ ہوا ہی نہیں»: غلط، شاید کچھ لکھا ہی نہ گیا ہو یا سب مٹا دیا گیا ہو۔"),
 # find -newer
 "cit.f.find_newer.enfant": T("On pose un repère, puis on demande : qu'est-ce qui a bougé depuis ?", "We set a marker, then ask: what has changed since?", "Ponemos una marca y luego preguntamos: ¿qué ha cambiado desde entonces?", "Wir setzen eine Markierung und fragen dann: Was hat sich seitdem verändert?", "Mettiamo un segnale e poi chiediamo: cosa è cambiato da allora?", "Pomos um marco e depois perguntamos: o que mudou desde então?", "Ставим метку и спрашиваем: что изменилось с тех пор?", "先放个标记，再问：那之后什么动过？", "目印を置いて、たずねる：あれから何が動いた？", "एक निशान रखते हैं, फिर पूछते हैं: तब से क्या बदला?", "نضع علامة ثم نسأل: ما الذي تغيّر منذئذ؟", "একটা চিহ্ন রাখি, তারপর জিজ্ঞেস করি: তারপর থেকে কী বদলেছে?", "Kita pasang penanda, lalu bertanya: apa yang berubah sejak itu?", "ایک نشان رکھتے ہیں، پھر پوچھتے ہیں: تب سے کیا بدلا؟"),
 "cit.f.find_newer.grands": T("find -newer f compare la date de modification à celle de f ; -name filtre par motif ; -delete efface ce qui est trouvé.", "find -newer f compares modification time with f's; -name filters by pattern; -delete erases what is found.", "find -newer f compara la fecha de modificación con la de f; -name filtra por patrón; -delete borra lo encontrado.", "find -newer f vergleicht die Änderungszeit mit der von f; -name filtert nach Muster; -delete löscht das Gefundene.", "find -newer f confronta la data di modifica con quella di f; -name filtra per motivo; -delete cancella ciò che trova.", "find -newer f compara a data de modificação com a de f; -name filtra por padrão; -delete apaga o encontrado.", "find -newer f сравнивает время изменения со временем f; -name фильтрует по шаблону; -delete удаляет найденное.", "find -newer f 拿修改时间跟 f 比；-name 按模式筛；-delete 删掉找到的。", "find -newer f は変更時刻を f とくらべる。-name はパターンでしぼる。-delete は見つけたものを消す。", "find -newer f बदलाव का समय f से मिलाता है; -name पैटर्न से छाँटता है; -delete मिला हुआ मिटाता है।", "يقارن find -newer f وقت التعديل بوقت f؛ ويصفّي -name بالنمط؛ ويحذف -delete ما وُجد.", "find -newer f পরিবর্তনের সময় f-এর সাথে মেলায়; -name প্যাটার্নে ছাঁকে; -delete যা পায় মুছে দেয়।", "find -newer f membandingkan waktu ubah dengan milik f; -name menyaring pola; -delete menghapus temuan.", "find -newer f تبدیلی کا وقت f سے ملاتا ہے؛ -name پیٹرن سے چھانتا ہے؛ -delete ملا ہوا مٹاتا ہے۔"),
 "cit.f.find_newer.limite": T("Une date se change facilement (touch) : elle aide l'enquête, elle ne prouve rien seule.", "A date is easy to change (touch): it helps an investigation but proves nothing on its own.", "Una fecha se cambia fácilmente (touch): ayuda a la investigación, no prueba nada sola.", "Ein Datum lässt sich leicht ändern (touch): Es hilft der Ermittlung, beweist allein nichts.", "Una data si cambia facilmente (touch): aiuta l'indagine, da sola non prova nulla.", "Uma data muda fácil (touch): ajuda a investigação, sozinha não prova nada.", "Дату легко изменить (touch): она помогает расследованию, но сама ничего не доказывает.", "日期很容易改（touch）：它能帮调查，单靠它证明不了什么。", "日付はかんたんに変えられる（touch）。調査の助けにはなるが、それだけでは証拠にならない。", "तारीख़ आसानी से बदलती है (touch): यह जाँच में मदद करती है, अकेले कुछ साबित नहीं करती।", "يسهل تغيير التاريخ (touch): يساعد التحقيق ولا يثبت شيئًا وحده.", "তারিখ সহজে বদলানো যায় (touch): তদন্তে সাহায্য করে, একা কিছু প্রমাণ করে না।", "Tanggal mudah diubah (touch): membantu penyelidikan, tapi sendirian tak membuktikan apa-apa.", "تاریخ آسانی سے بدلتی ہے (touch): یہ تفتیش میں مدد کرتی ہے، اکیلے کچھ ثابت نہیں کرتی۔"),
 "cit.f.find_newer.idee": T("« -newer veut dire créé après » : faux, c'est la date de dernière modification.", "“-newer means created after”: false, it's the last modification time.", "«-newer significa creado después»: falso, es la fecha de última modificación.", "„-newer heißt danach erstellt“: falsch, es ist die letzte Änderungszeit.", "«-newer vuol dire creato dopo»: falso, è la data dell'ultima modifica.", "«-newer quer dizer criado depois»: falso, é a data da última modificação.", "«-newer значит создан позже» — неверно, это время последнего изменения.", "“-newer 表示之后创建的”：错，看的是最后修改时间。", "「-newer はあとで作られたもの」：まちがい。最後に変えた時刻のこと。", "«-newer मतलब बाद में बना»: गलत, यह आख़िरी बदलाव का समय है।", "«-newer يعني أُنشئ بعد»: خطأ، إنه وقت آخر تعديل.", "«-newer মানে পরে তৈরি»: ভুল, এটা শেষ পরিবর্তনের সময়।", "«-newer berarti dibuat setelahnya»: salah, itu waktu ubah terakhir.", "«-newer یعنی بعد میں بنا»: غلط، یہ آخری تبدیلی کا وقت ہے۔"),
 # cheval de Troie
 "cit.f.cheval.enfant": T("Un cheval de Troie a l'air d'un cadeau, mais cache un piège : on lit avant de lancer.", "A Trojan horse looks like a present but hides a trap: read before you run.", "Un caballo de Troya parece un regalo pero esconde una trampa: se lee antes de ejecutar.", "Ein Trojanisches Pferd sieht aus wie ein Geschenk, versteckt aber eine Falle: Erst lesen, dann starten.", "Un cavallo di Troia sembra un regalo ma nasconde una trappola: si legge prima di lanciare.", "Um cavalo de Troia parece presente mas esconde armadilha: leia antes de rodar.", "Троянский конь похож на подарок, но прячет ловушку: сначала читаем, потом запускаем.", "特洛伊木马看着像礼物，其实藏着陷阱：先读再运行。", "トロイの木馬はプレゼントに見えて、わなをかくしている：実行する前に読む。", "ट्रोजन घोड़ा तोहफ़े जैसा दिखता है पर जाल छिपाता है: चलाने से पहले पढ़ो।", "حصان طروادة يبدو هدية لكنه يخفي فخًا: اقرأ قبل أن تشغّل.", "ট্রয়ের ঘোড়া দেখতে উপহার, কিন্তু ফাঁদ লুকায়: চালানোর আগে পড়ো।", "Kuda Troya tampak seperti hadiah tapi menyembunyikan jebakan: baca dulu sebelum menjalankan.", "ٹروجن گھوڑا تحفہ لگتا ہے مگر جال چھپاتا ہے: چلانے سے پہلے پڑھو۔"),
 "cit.f.cheval.grands": T("Un script n'est lancé que s'il est exécutable (x) ou passé à un interpréteur ; lire (cat, grep) puis retirer x (chmod -x) neutralise le piège.", "A script only runs if it is executable (x) or given to an interpreter; reading (cat, grep) then removing x (chmod -x) neutralises the trap.", "Un script solo se ejecuta si es ejecutable (x) o se pasa a un intérprete; leer (cat, grep) y quitar x (chmod -x) neutraliza la trampa.", "Ein Skript läuft nur, wenn es ausführbar (x) ist oder einem Interpreter übergeben wird; lesen (cat, grep) und x entfernen (chmod -x) entschärft die Falle.", "Uno script parte solo se è eseguibile (x) o dato a un interprete; leggere (cat, grep) e togliere x (chmod -x) neutralizza la trappola.", "Um script só roda se for executável (x) ou passado a um interpretador; ler (cat, grep) e tirar x (chmod -x) neutraliza a armadilha.", "Скрипт запускается, только если он исполняемый (x) или передан интерпретатору; прочитать (cat, grep) и снять x (chmod -x) — и ловушка обезврежена.", "脚本只有可执行（x）或交给解释器时才会运行；先读（cat、grep），再拿掉 x（chmod -x），陷阱就失效了。", "スクリプトは実行可能（x）か、インタプリタにわたしたときだけ動く。読んで（cat、grep）、x を取れば（chmod -x）わなは無力になる。", "स्क्रिप्ट तभी चलती है जब वह x हो या इंटरप्रेटर को दी जाए; पढ़ना (cat, grep) और x हटाना (chmod -x) जाल बेअसर करता है।", "لا يعمل السكربت إلا إذا كان قابلًا للتنفيذ (x) أو مُرّر لمفسّر؛ القراءة (cat، grep) ثم نزع x (chmod -x) تُبطل الفخ.", "স্ক্রিপ্ট তখনই চলে যখন x থাকে বা ইন্টারপ্রেটারকে দেওয়া হয়; পড়া (cat, grep) আর x সরানো (chmod -x) ফাঁদ অকেজো করে।", "Skrip hanya jalan bila executable (x) atau diberikan ke interpreter; membaca (cat, grep) lalu mencabut x (chmod -x) melumpuhkan jebakan.", "اسکرپٹ تب ہی چلتا ہے جب x ہو یا انٹرپریٹر کو دیا جائے؛ پڑھنا (cat، grep) پھر x ہٹانا (chmod -x) جال بے اثر کرتا ہے۔"),
 "cit.f.cheval.limite": T("Un vrai piège peut être caché (encodé, téléchargé plus tard) : en cas de doute, on ne lance pas du tout.", "A real trap may be hidden (encoded, downloaded later): when in doubt, don't run it at all.", "Una trampa real puede estar oculta (codificada, descargada luego): ante la duda, no se ejecuta.", "Eine echte Falle kann versteckt sein (kodiert, später geladen): Im Zweifel gar nicht starten.", "Una vera trappola può essere nascosta (codificata, scaricata dopo): nel dubbio, non si lancia affatto.", "Uma armadilha real pode estar escondida (codificada, baixada depois): na dúvida, não rode.", "Настоящая ловушка может быть скрыта (закодирована, скачана позже): сомневаешься — не запускай вовсе.", "真正的陷阱可能藏得更深（编码过、之后才下载）：拿不准就干脆别运行。", "本物のわなはかくされていることもある（暗号化、あとでダウンロード）。迷ったら、そもそも実行しない。", "असली जाल छिपा हो सकता है (एन्कोड, बाद में डाउनलोड): शक हो तो बिल्कुल मत चलाओ।", "قد يكون الفخ الحقيقي مخفيًا (مرمّزًا، يُنزَّل لاحقًا): عند الشك لا تشغّل أبدًا.", "আসল ফাঁদ লুকানো থাকতে পারে (এনকোড, পরে ডাউনলোড): সন্দেহ হলে চালিয়োই না।", "Jebakan sungguhan bisa tersembunyi (dikodekan, diunduh belakangan): bila ragu, jangan jalankan sama sekali.", "اصل جال چھپا ہو سکتا ہے (انکوڈ، بعد میں ڈاؤن لوڈ): شک ہو تو بالکل نہ چلاؤ۔"),
 "cit.f.cheval.idee": T("« Un antivirus suffit, pas besoin de lire » : faux, beaucoup de pièges ne sont reconnus par aucun antivirus.", "“An antivirus is enough, no need to read”: false, many traps are not recognised by any antivirus.", "«Basta un antivirus, no hace falta leer»: falso, muchas trampas no las reconoce ningún antivirus.", "„Ein Virenscanner reicht, lesen unnötig“: falsch, viele Fallen erkennt kein Virenscanner.", "«Basta un antivirus, non serve leggere»: falso, molte trappole non sono riconosciute da nessun antivirus.", "«Um antivírus basta, não precisa ler»: falso, muitas armadilhas não são reconhecidas por nenhum antivírus.", "«Хватит антивируса, читать не нужно» — неверно: многие ловушки не распознаёт ни один антивирус.", "“有杀毒软件就够了，不用读”：错，很多陷阱没有任何杀毒软件能认出来。", "「ウイルス対策ソフトがあれば読まなくていい」：まちがい。どのソフトにも見つからないわなはたくさんある。", "«एंटीवायरस काफ़ी है, पढ़ने की ज़रूरत नहीं»: गलत, कई जाल कोई एंटीवायरस नहीं पहचानता।", "«يكفي مضاد الفيروسات ولا حاجة للقراءة»: خطأ، كثير من الفخاخ لا يتعرّف عليها أي مضاد.", "«অ্যান্টিভাইরাসই যথেষ্ট, পড়ার দরকার নেই»: ভুল, অনেক ফাঁদ কোনো অ্যান্টিভাইরাস চেনে না।", "«Antivirus cukup, tak perlu membaca»: salah, banyak jebakan tak dikenali antivirus mana pun.", "«اینٹی وائرس کافی ہے، پڑھنے کی ضرورت نہیں»: غلط، کئی جال کوئی اینٹی وائرس نہیں پہچانتا۔"),
 # processus suspects
 "cit.f.processus_suspects.enfant": T("Des programmes qui travaillent en cachette fatiguent l'ordinateur ; on les trouve avec ps et on les arrête avec kill.", "Programs working in secret tire the computer; find them with ps and stop them with kill.", "Programas que trabajan a escondidas cansan al ordenador; se encuentran con ps y se detienen con kill.", "Heimlich arbeitende Programme ermüden den Computer; man findet sie mit ps und stoppt sie mit kill.", "Programmi che lavorano di nascosto stancano il computer; si trovano con ps e si fermano con kill.", "Programas que trabalham escondidos cansam o computador; ache com ps e pare com kill.", "Программы, работающие тайком, утомляют компьютер; их находят ps и останавливают kill.", "偷偷干活的程序会把电脑累坏；用 ps 找出来，用 kill 停掉。", "こっそり働くプログラムはコンピュータをつかれさせる。ps で見つけて kill で止める。", "छिपकर काम करने वाले प्रोग्राम कंप्यूटर थकाते हैं; ps से ढूँढो, kill से रोको।", "البرامج التي تعمل خفية تُتعب الحاسوب؛ نجدها بـ ps ونوقفها بـ kill.", "লুকিয়ে কাজ করা প্রোগ্রাম কম্পিউটারকে ক্লান্ত করে; ps দিয়ে খোঁজো, kill দিয়ে থামাও।", "Program yang bekerja diam-diam membuat komputer lelah; temukan dengan ps dan hentikan dengan kill.", "چھپ کر کام کرنے والے پروگرام کمپیوٹر تھکاتے ہیں؛ ps سے ڈھونڈو، kill سے روکو۔"),
 "cit.f.processus_suspects.grands": T("ps aux liste tous les processus (utilisateur, PID, %CPU, commande) ; kill PID envoie SIGTERM. Un nom de processus peut mentir (exec -a).", "ps aux lists all processes (user, PID, %CPU, command); kill PID sends SIGTERM. A process name can lie (exec -a).", "ps aux lista todos los procesos (usuario, PID, %CPU, orden); kill PID envía SIGTERM. El nombre de un proceso puede mentir (exec -a).", "ps aux listet alle Prozesse (Benutzer, PID, %CPU, Befehl); kill PID sendet SIGTERM. Ein Prozessname kann lügen (exec -a).", "ps aux elenca tutti i processi (utente, PID, %CPU, comando); kill PID invia SIGTERM. Il nome di un processo può mentire (exec -a).", "ps aux lista todos os processos (usuário, PID, %CPU, comando); kill PID manda SIGTERM. O nome de um processo pode mentir (exec -a).", "ps aux выводит все процессы (пользователь, PID, %CPU, команда); kill PID посылает SIGTERM. Имя процесса может лгать (exec -a).", "ps aux 列出全部进程（用户、PID、%CPU、命令）；kill PID 发送 SIGTERM。进程名可能是假的（exec -a）。", "ps aux は全プロセスを表示（ユーザー、PID、%CPU、コマンド）。kill PID は SIGTERM を送る。プロセス名はうそをつける（exec -a）。", "ps aux सारे प्रोसेस दिखाता है (उपयोगकर्ता, PID, %CPU, कमांड); kill PID SIGTERM भेजता है। प्रोसेस का नाम झूठा हो सकता है (exec -a)।", "يعرض ps aux كل العمليات (المستخدم، PID، %CPU، الأمر)؛ ويرسل kill PID إشارة SIGTERM. قد يكذب اسم العملية (exec -a).", "ps aux সব প্রসেস দেখায় (ব্যবহারকারী, PID, %CPU, কমান্ড); kill PID SIGTERM পাঠায়। প্রসেসের নাম মিথ্যা হতে পারে (exec -a)।", "ps aux menampilkan semua proses (pengguna, PID, %CPU, perintah); kill PID mengirim SIGTERM. Nama proses bisa bohong (exec -a).", "ps aux سارے پروسیس دکھاتا ہے (صارف، PID، %CPU، کمانڈ)؛ kill PID، SIGTERM بھیجتا ہے۔ پروسیس کا نام جھوٹا ہو سکتا ہے (exec -a)۔"),
 "cit.f.processus_suspects.limite": T("Les fantômes du jeu ne font que dormir ; un vrai processus malveillant peut se relancer ou se cacher mieux.", "The game's ghosts only sleep; a real malicious process may restart itself or hide better.", "Los fantasmas del juego solo duermen; un proceso malicioso real puede relanzarse o esconderse mejor.", "Die Geister des Spiels schlafen nur; ein echter Schadprozess kann sich neu starten oder besser verstecken.", "I fantasmi del gioco dormono e basta; un vero processo malevolo può riavviarsi o nascondersi meglio.", "Os fantasmas do jogo só dormem; um processo malicioso real pode se reiniciar ou se esconder melhor.", "Призраки игры только спят; настоящий вредный процесс может перезапуститься или лучше спрятаться.", "游戏里的幽灵只会睡觉；真正的恶意进程可能会自己重启，或藏得更深。", "ゲームのゆうれいはねむるだけ。本物の悪いプロセスは自分で起き直したり、もっとうまくかくれたりする。", "खेल के भूत बस सोते हैं; असली बुरा प्रोसेस खुद को फिर चला सकता है या बेहतर छिप सकता है।", "أشباح اللعبة تنام فقط؛ أما العملية الخبيثة الحقيقية فقد تعيد تشغيل نفسها أو تختبئ أفضل.", "খেলার ভূত শুধু ঘুমায়; আসল ক্ষতিকর প্রসেস নিজেকে আবার চালাতে বা আরও ভালো লুকাতে পারে।", "Hantu permainan hanya tidur; proses jahat sungguhan bisa menyalakan diri lagi atau bersembunyi lebih baik.", "کھیل کے بھوت بس سوتے ہیں؛ اصل بُرا پروسیس خود کو دوبارہ چلا سکتا ہے یا بہتر چھپ سکتا ہے۔"),
 "cit.f.processus_suspects.idee": T("« kill détruit le programme » : faux, il arrête une exécution ; le fichier du programme reste là.", "“kill destroys the program”: false, it stops one run; the program file stays.", "«kill destruye el programa»: falso, detiene una ejecución; el archivo del programa sigue ahí.", "„kill zerstört das Programm“: falsch, es stoppt eine Ausführung; die Programmdatei bleibt.", "«kill distrugge il programma»: falso, ferma un'esecuzione; il file del programma resta.", "«kill destrói o programa»: falso, ele para uma execução; o arquivo do programa continua.", "«kill уничтожает программу» — неверно: он останавливает один запуск, файл программы остаётся.", "“kill 会毁掉程序”：错，它只是停掉一次运行，程序文件还在。", "「kill はプログラムをこわす」：まちがい。実行を止めるだけで、プログラムのファイルはのこる。", "«kill प्रोग्राम मिटा देता है»: गलत, यह एक चलना रोकता है; प्रोग्राम की फ़ाइल रहती है।", "«kill يدمّر البرنامج»: خطأ، يوقف تشغيلًا واحدًا ويبقى ملف البرنامج.", "«kill প্রোগ্রাম ধ্বংস করে»: ভুল, এটা একটা চালানো থামায়; প্রোগ্রামের ফাইল থেকে যায়।", "«kill menghancurkan program»: salah, ia menghentikan satu jalannya; berkas program tetap ada.", "«kill پروگرام تباہ کر دیتا ہے»: غلط، یہ ایک چلنا روکتا ہے؛ پروگرام کی فائل رہتی ہے۔"),
 # empreinte
 "cit.f.empreinte.enfant": T("Chaque fichier a une empreinte, comme un doigt : si le fichier change, l'empreinte change.", "Every file has a fingerprint: if the file changes, the fingerprint changes.", "Cada archivo tiene una huella: si el archivo cambia, la huella cambia.", "Jede Datei hat einen Fingerabdruck: Ändert sich die Datei, ändert sich der Abdruck.", "Ogni file ha un'impronta: se il file cambia, l'impronta cambia.", "Cada arquivo tem uma impressão digital: se o arquivo muda, ela muda.", "У каждого файла есть отпечаток: файл изменился — отпечаток тоже.", "每个文件都有指纹：文件一变，指纹就变。", "ファイルにはそれぞれ指紋がある：ファイルが変われば指紋も変わる。", "हर फ़ाइल का फ़िंगरप्रिंट होता है: फ़ाइल बदली तो फ़िंगरप्रिंट बदला।", "لكل ملف بصمة: إذا تغيّر الملف تغيّرت البصمة.", "প্রতিটা ফাইলের ছাপ আছে: ফাইল বদলালে ছাপ বদলায়।", "Setiap berkas punya sidik jari: berkas berubah, sidiknya berubah.", "ہر فائل کا فنگرپرنٹ ہوتا ہے: فائل بدلی تو فنگرپرنٹ بدلا۔"),
 "cit.f.empreinte.grands": T("SHA-256 donne 256 bits (64 hexadécimaux) ; sha256sum -c vérifie une liste d'empreintes. Sert à vérifier un téléchargement ou détecter une modification.", "SHA-256 gives 256 bits (64 hex digits); sha256sum -c checks a list of fingerprints. Used to verify a download or detect a change.", "SHA-256 da 256 bits (64 hexadecimales); sha256sum -c verifica una lista de huellas. Sirve para verificar descargas o detectar cambios.", "SHA-256 liefert 256 Bit (64 Hex-Zeichen); sha256sum -c prüft eine Abdruckliste. Zum Prüfen von Downloads oder Erkennen von Änderungen.", "SHA-256 dà 256 bit (64 esadecimali); sha256sum -c verifica una lista di impronte. Serve a verificare un download o rilevare una modifica.", "SHA-256 dá 256 bits (64 hexadecimais); sha256sum -c confere uma lista de impressões. Serve para verificar downloads ou detectar alterações.", "SHA-256 даёт 256 бит (64 шестнадцатеричных знака); sha256sum -c проверяет список отпечатков. Нужен для проверки загрузок и поиска изменений.", "SHA-256 产生 256 位（64 个十六进制字符）；sha256sum -c 按清单核对指纹。用来检查下载、发现改动。", "SHA-256 は 256 ビット（16進数64文字）。sha256sum -c は指紋の一覧を確かめる。ダウンロードの確認や変更の発見に使う。", "SHA-256 से 256 बिट (64 हेक्साडेसिमल) मिलते हैं; sha256sum -c फ़िंगरप्रिंट सूची जाँचता है। डाउनलोड जाँचने या बदलाव पकड़ने के काम आता है।", "يعطي SHA-256 ‏256 بتًا (64 رمزًا ست عشريًا)؛ ويتحقق sha256sum -c من قائمة بصمات. يُستخدم للتحقق من التنزيلات أو كشف التعديل.", "SHA-256 ২৫৬ বিট দেয় (৬৪টা হেক্স অক্ষর); sha256sum -c ছাপের তালিকা যাচাই করে। ডাউনলোড যাচাই বা পরিবর্তন ধরতে কাজে লাগে।", "SHA-256 memberi 256 bit (64 heksadesimal); sha256sum -c memeriksa daftar sidik. Untuk memverifikasi unduhan atau mendeteksi perubahan.", "SHA-256 سے 256 بٹ (64 ہیکسا ڈیسیمل) ملتے ہیں؛ sha256sum -c فنگرپرنٹ فہرست جانچتا ہے۔ ڈاؤن لوڈ جانچنے یا تبدیلی پکڑنے کے کام آتا ہے۔"),
 "cit.f.empreinte.limite": T("Contrairement à un doigt, l'empreinte ne dit pas QUI a changé le fichier ; et si l'intrus change aussi la liste d'empreintes, elle ne prouve plus rien.", "Unlike a finger, the fingerprint doesn't say WHO changed the file; and if the intruder also changes the fingerprint list, it proves nothing.", "A diferencia de un dedo, la huella no dice QUIÉN cambió el archivo; y si el intruso cambia también la lista, ya no prueba nada.", "Anders als ein Finger sagt der Abdruck nicht, WER die Datei änderte; ändert der Eindringling auch die Liste, beweist er nichts mehr.", "A differenza di un dito, l'impronta non dice CHI ha cambiato il file; e se l'intruso cambia anche la lista, non prova più nulla.", "Diferente de um dedo, a impressão não diz QUEM mudou o arquivo; e se o intruso mudar também a lista, não prova mais nada.", "В отличие от пальца, отпечаток не говорит, КТО изменил файл; а если нарушитель поменяет и список отпечатков, он ничего не докажет.", "跟手指不一样，指纹说不出是谁改了文件；如果入侵者把指纹清单也改了，它就什么也证明不了。", "指とちがって、指紋はだれが変えたかを教えない。侵入者が指紋の一覧まで変えたら、もう何の証拠にもならない。", "उँगली के उलट, फ़िंगरप्रिंट यह नहीं बताता कि फ़ाइल किसने बदली; और अगर घुसपैठिया सूची भी बदल दे तो कुछ साबित नहीं होता।", "على عكس الإصبع، لا تقول البصمة من غيّر الملف؛ وإن غيّر الدخيل قائمة البصمات أيضًا فلن تثبت شيئًا.", "আঙুলের মতো নয়, ছাপ বলে না কে ফাইল বদলেছে; আর অনুপ্রবেশকারী তালিকাও বদলালে কিছুই প্রমাণ হয় না।", "Tak seperti jari, sidik tak memberi tahu SIAPA yang mengubah berkas; dan jika penyusup ikut mengubah daftarnya, tak ada yang terbukti.", "انگلی کے برعکس، فنگرپرنٹ یہ نہیں بتاتا کہ فائل کس نے بدلی؛ اور اگر گھس بیٹھیا فہرست بھی بدل دے تو کچھ ثابت نہیں ہوتا۔"),
 "cit.f.empreinte.idee": T("« Une empreinte, c'est un chiffrement : on peut retrouver le fichier » : faux, on ne revient jamais en arrière.", "“A fingerprint is encryption: you can get the file back”: false, there's no going back.", "«Una huella es un cifrado: se puede recuperar el archivo»: falso, nunca se vuelve atrás.", "„Ein Abdruck ist Verschlüsselung: Man bekommt die Datei zurück“: falsch, es gibt kein Zurück.", "«Un'impronta è una cifratura: si può riavere il file»: falso, non si torna mai indietro.", "«Impressão é cifragem: dá para recuperar o arquivo»: falso, não há volta.", "«Отпечаток — это шифр, по нему можно восстановить файл» — неверно, назад пути нет.", "“指纹就是加密，能还原文件”：错，永远倒推不回去。", "「指紋は暗号だから、ファイルをとりもどせる」：まちがい。逆もどりはできない。", "«फ़िंगरप्रिंट एन्क्रिप्शन है, फ़ाइल वापस मिल सकती है»: गलत, वापसी कभी नहीं।", "«البصمة تشفير ويمكن استعادة الملف»: خطأ، لا رجوع أبدًا.", "«ছাপ মানে এনক্রিপশন, ফাইল ফেরত পাওয়া যায়»: ভুল, কখনো ফেরা যায় না।", "«Sidik itu enkripsi, berkas bisa dikembalikan»: salah, tak bisa mundur.", "«فنگرپرنٹ انکرپشن ہے، فائل واپس مل سکتی ہے»: غلط، واپسی کبھی نہیں۔"),
 # sauvegarde
 "cit.f.sauvegarde.enfant": T("Une sauvegarde est un coffre de secours : on range une copie AVANT le problème.", "A backup is a spare chest: you put a copy away BEFORE trouble comes.", "Una copia de seguridad es un cofre de reserva: se guarda una copia ANTES del problema.", "Eine Sicherung ist eine Ersatztruhe: Man legt eine Kopie VOR dem Problem ab.", "Un backup è un forziere di riserva: si mette via una copia PRIMA del problema.", "Um backup é um baú reserva: guarda-se uma cópia ANTES do problema.", "Резервная копия — запасной сундук: копию кладут ДО беды.", "备份就是备用宝箱：在出问题之前先放一份副本。", "バックアップは予備の宝箱：問題が起きる前にコピーをしまっておく。", "बैकअप एक अतिरिक्त संदूक है: मुसीबत से पहले एक प्रति रख दो।", "النسخة الاحتياطية صندوق احتياطي: نحفظ نسخة قبل المشكلة.", "ব্যাকআপ হলো বাড়তি সিন্দুক: সমস্যার আগে একটা কপি রেখে দাও।", "Cadangan adalah peti serep: simpan salinan SEBELUM masalah datang.", "بیک اپ ایک فالتو صندوق ہے: مصیبت سے پہلے ایک نقل رکھ دو۔"),
 "cit.f.sauvegarde.grands": T("tar c (créer), x (extraire), t (lister), z (gzip), f (fichier). Règle 3-2-1 : 3 copies, 2 supports, 1 hors ligne ; et tester la restauration.", "tar c (create), x (extract), t (list), z (gzip), f (file). 3-2-1 rule: 3 copies, 2 media, 1 offline; and test restoring.", "tar c (crear), x (extraer), t (listar), z (gzip), f (archivo). Regla 3-2-1: 3 copias, 2 soportes, 1 desconectada; y probar la restauración.", "tar c (erstellen), x (entpacken), t (auflisten), z (gzip), f (Datei). 3-2-1-Regel: 3 Kopien, 2 Medien, 1 offline; und Wiederherstellung testen.", "tar c (creare), x (estrarre), t (elencare), z (gzip), f (file). Regola 3-2-1: 3 copie, 2 supporti, 1 offline; e provare il ripristino.", "tar c (criar), x (extrair), t (listar), z (gzip), f (arquivo). Regra 3-2-1: 3 cópias, 2 mídias, 1 desconectada; e testar a restauração.", "tar c (создать), x (извлечь), t (список), z (gzip), f (файл). Правило 3-2-1: 3 копии, 2 носителя, 1 вне сети; и проверять восстановление.", "tar 的 c（创建）、x（解开）、t（列出）、z（gzip）、f（文件）。3-2-1 规则：3 份副本、2 种介质、1 份离线；还要测试能不能恢复。", "tar の c（作る）、x（取り出す）、t（一覧）、z（gzip）、f（ファイル）。3-2-1 ルール：コピー3つ、媒体2種、1つはオフライン。復元のテストも。", "tar c (बनाना), x (निकालना), t (सूची), z (gzip), f (फ़ाइल)। 3-2-1 नियम: 3 प्रतियाँ, 2 माध्यम, 1 ऑफ़लाइन; और वापसी की जाँच।", "tar c (إنشاء)، x (استخراج)، t (سرد)، z (gzip)، f (ملف). قاعدة 3-2-1: 3 نسخ، وسيطان، 1 غير متصلة؛ واختبار الاستعادة.", "tar c (বানানো), x (বের করা), t (তালিকা), z (gzip), f (ফাইল)। ৩-২-১ নিয়ম: ৩টা কপি, ২ ধরনের মাধ্যম, ১টা অফলাইন; আর ফেরানো পরীক্ষা।", "tar c (buat), x (ekstrak), t (daftar), z (gzip), f (berkas). Aturan 3-2-1: 3 salinan, 2 media, 1 luring; dan uji pemulihan.", "tar c (بنانا)، x (نکالنا)، t (فہرست)، z (gzip)، f (فائل)۔ 3-2-1 اصول: 3 نقلیں، 2 ذریعے، 1 آف لائن؛ اور واپسی کی جانچ۔"),
 "cit.f.sauvegarde.limite": T("Une sauvegarde dans le même dossier peut être verrouillée avec le reste : une vraie copie de secours est ailleurs.", "A backup in the same folder can get locked with the rest: a real spare copy lives elsewhere.", "Una copia en la misma carpeta puede bloquearse con el resto: una copia real está en otro sitio.", "Eine Sicherung im selben Ordner kann mit verriegelt werden: Eine echte Ersatzkopie liegt woanders.", "Un backup nella stessa cartella può essere bloccato col resto: una vera copia di riserva sta altrove.", "Um backup na mesma pasta pode ser trancado junto: uma cópia reserva de verdade fica em outro lugar.", "Копию в той же папке могут запереть вместе со всем остальным: настоящий запас хранят в другом месте.", "放在同一个文件夹里的备份可能被一起锁住：真正的备用副本要放在别处。", "同じフォルダのバックアップはいっしょにロックされうる。本当の予備は別の場所に。", "उसी फ़ोल्डर का बैकअप बाकी के साथ बंद हो सकता है: असली अतिरिक्त प्रति कहीं और रहती है।", "قد تُقفل النسخة الموجودة في المجلد نفسه مع الباقي: النسخة الاحتياطية الحقيقية في مكان آخر.", "একই ফোল্ডারের ব্যাকআপ বাকিটার সাথে বন্ধ হতে পারে: আসল বাড়তি কপি অন্য জায়গায় থাকে।", "Cadangan di folder yang sama bisa ikut terkunci: salinan serep sejati ada di tempat lain.", "اسی فولڈر کا بیک اپ باقی کے ساتھ بند ہو سکتا ہے: اصل فالتو نقل کہیں اور رہتی ہے۔"),
 "cit.f.sauvegarde.idee": T("« Payer la rançon rend les fichiers » : faux, rien ne le garantit ; seule la sauvegarde le fait.", "“Paying the ransom gets the files back”: false, nothing guarantees it; only a backup does.", "«Pagar el rescate devuelve los archivos»: falso, nada lo garantiza; solo la copia lo hace.", "„Lösegeld zahlen bringt die Dateien zurück“: falsch, nichts garantiert es; nur die Sicherung.", "«Pagare il riscatto restituisce i file»: falso, niente lo garantisce; solo il backup.", "«Pagar o resgate devolve os arquivos»: falso, nada garante; só o backup.", "«Заплатишь выкуп — вернёшь файлы» — неверно, это ничем не гарантировано; помогает только резервная копия.", "“付了赎金就能拿回文件”：错，没人能保证；只有备份靠得住。", "「身代金をはらえばファイルがもどる」：まちがい。何の保証もない。もどせるのはバックアップだけ。", "«फिरौती देने से फ़ाइलें लौटती हैं»: गलत, कोई गारंटी नहीं; सिर्फ़ बैकअप लौटाता है।", "«دفع الفدية يعيد الملفات»: خطأ، لا شيء يضمن ذلك؛ النسخة الاحتياطية وحدها تفعل.", "«মুক্তিপণ দিলে ফাইল ফেরে»: ভুল, কোনো নিশ্চয়তা নেই; শুধু ব্যাকআপই ফেরায়।", "«Membayar tebusan mengembalikan berkas»: salah, tak ada jaminan; hanya cadangan yang bisa.", "«تاوان دینے سے فائلیں واپس ملتی ہیں»: غلط، کوئی ضمانت نہیں؛ صرف بیک اپ واپس لاتا ہے۔"),
 # chiffrement
 "cit.f.chiffrement.enfant": T("Chiffrer, c'est enfermer un texte dans un coffre : sans la clé, impossible de le lire.", "Encrypting is locking a text in a chest: without the key, impossible to read.", "Cifrar es encerrar un texto en un cofre: sin la llave, imposible de leer.", "Verschlüsseln heißt, einen Text in eine Truhe zu sperren: Ohne Schlüssel unlesbar.", "Cifrare è chiudere un testo in un forziere: senza la chiave, impossibile leggerlo.", "Cifrar é trancar um texto num baú: sem a chave, impossível ler.", "Шифровать — значит запереть текст в сундук: без ключа его не прочесть.", "加密就是把文字锁进宝箱：没有钥匙就读不了。", "暗号化は文を宝箱にしまうこと：鍵がなければ読めない。", "एन्क्रिप्ट करना यानी पाठ को संदूक में बंद करना: चाबी के बिना पढ़ना असंभव।", "التشفير هو حبس نص في صندوق: دون المفتاح يستحيل قراءته.", "এনক্রিপ্ট মানে লেখা সিন্দুকে বন্ধ করা: চাবি ছাড়া পড়া অসম্ভব।", "Mengenkripsi berarti mengunci teks di peti: tanpa kunci, tak bisa dibaca.", "انکرپٹ کرنا یعنی متن کو صندوق میں بند کرنا: چابی کے بغیر پڑھنا ناممکن۔"),
 "cit.f.chiffrement.grands": T("openssl enc -aes-256-cbc -pbkdf2 : chiffrement symétrique AES, clé dérivée du mot de passe par PBKDF2 avec un sel ; gpg --symmetric fait de même.", "openssl enc -aes-256-cbc -pbkdf2: symmetric AES encryption, key derived from the password by PBKDF2 with a salt; gpg --symmetric does the same.", "openssl enc -aes-256-cbc -pbkdf2: cifrado simétrico AES, clave derivada de la contraseña por PBKDF2 con sal; gpg --symmetric hace lo mismo.", "openssl enc -aes-256-cbc -pbkdf2: symmetrische AES-Verschlüsselung, Schlüssel per PBKDF2 mit Salz aus dem Passwort; gpg --symmetric macht dasselbe.", "openssl enc -aes-256-cbc -pbkdf2: cifratura simmetrica AES, chiave derivata dalla password con PBKDF2 e un sale; gpg --symmetric fa lo stesso.", "openssl enc -aes-256-cbc -pbkdf2: cifragem simétrica AES, chave derivada da senha por PBKDF2 com sal; gpg --symmetric faz o mesmo.", "openssl enc -aes-256-cbc -pbkdf2: симметричное шифрование AES, ключ выводится из пароля через PBKDF2 с солью; gpg --symmetric делает то же.", "openssl enc -aes-256-cbc -pbkdf2：对称加密 AES，用 PBKDF2 加盐从密码推出钥匙；gpg --symmetric 也一样。", "openssl enc -aes-256-cbc -pbkdf2：共通鍵暗号 AES。鍵は PBKDF2 と塩でパスワードから作る。gpg --symmetric も同じ。", "openssl enc -aes-256-cbc -pbkdf2: सममित AES एन्क्रिप्शन, चाबी पासवर्ड से PBKDF2 और नमक से; gpg --symmetric भी यही करता है।", "openssl enc -aes-256-cbc -pbkdf2: تشفير AES متماثل، والمفتاح مشتق من كلمة المرور بـ PBKDF2 مع ملح؛ وgpg --symmetric يفعل المثل.", "openssl enc -aes-256-cbc -pbkdf2: প্রতিসম AES এনক্রিপশন, PBKDF2 আর লবণ দিয়ে পাসওয়ার্ড থেকে চাবি; gpg --symmetric-ও একই করে।", "openssl enc -aes-256-cbc -pbkdf2: enkripsi simetris AES, kunci diturunkan dari sandi lewat PBKDF2 dengan garam; gpg --symmetric sama.", "openssl enc -aes-256-cbc -pbkdf2: ہم آہنگ AES انکرپشن، چابی پاس ورڈ سے PBKDF2 اور نمک سے؛ gpg --symmetric بھی یہی کرتا ہے۔"),
 "cit.f.chiffrement.limite": T("Le coffre protège le contenu, pas le fait qu'il existe ni sa taille ; et une clé faible s'ouvre par essais.", "The chest protects the contents, not the fact that it exists nor its size; and a weak key opens by guessing.", "El cofre protege el contenido, no su existencia ni su tamaño; y una llave débil se abre probando.", "Die Truhe schützt den Inhalt, nicht ihre Existenz oder Größe; ein schwacher Schlüssel lässt sich erraten.", "Il forziere protegge il contenuto, non il fatto che esista né la sua dimensione; e una chiave debole si apre per tentativi.", "O baú protege o conteúdo, não o fato de existir nem o tamanho; e uma chave fraca abre por tentativas.", "Сундук защищает содержимое, но не сам факт его существования и не размер; слабый ключ подбирают.", "宝箱保护的是内容，不能隐藏它的存在和大小；弱钥匙还会被试出来。", "宝箱が守るのは中身。あることや大きさまではかくせない。弱い鍵は当てずっぽうで開く。", "संदूक सामग्री बचाता है, उसका होना या आकार नहीं; और कमज़ोर चाबी अंदाज़े से खुलती है।", "يحمي الصندوق المحتوى لا وجوده ولا حجمه؛ والمفتاح الضعيف يُفتح بالتجربة.", "সিন্দুক ভেতরের জিনিস রক্ষা করে, থাকা বা আকার নয়; আর দুর্বল চাবি আন্দাজে খোলে।", "Peti melindungi isi, bukan keberadaannya atau ukurannya; kunci lemah terbuka dengan menebak.", "صندوق مواد بچاتا ہے، اس کا ہونا یا سائز نہیں؛ اور کمزور چابی اندازے سے کھلتی ہے۔"),
 "cit.f.chiffrement.idee": T("« Encoder en base64, c'est chiffrer » : faux, base64 se décode sans clé.", "“Base64 encoding is encryption”: false, base64 decodes without a key.", "«Codificar en base64 es cifrar»: falso, base64 se decodifica sin llave.", "„Base64 ist Verschlüsselung“: falsch, base64 lässt sich ohne Schlüssel dekodieren.", "«Codificare in base64 è cifrare»: falso, base64 si decodifica senza chiave.", "«Codificar em base64 é cifrar»: falso, base64 se decodifica sem chave.", "«Base64 — это шифр» — неверно, base64 раскодируется без ключа.", "“base64 编码就是加密”：错，base64 不用钥匙就能解开。", "「base64 は暗号」：まちがい。base64 は鍵なしでもどせる。", "«base64 एन्कोड करना एन्क्रिप्शन है»: गलत, base64 बिना चाबी के खुलता है।", "«الترميز بـ base64 تشفير»: خطأ، يُفك base64 دون مفتاح.", "«base64 মানে এনক্রিপশন»: ভুল, base64 চাবি ছাড়াই খোলে।", "«Base64 itu enkripsi»: salah, base64 bisa didekode tanpa kunci.", "«base64 انکرپشن ہے»: غلط، base64 بغیر چابی کے کھلتا ہے۔"),
 # hameçonnage
 "cit.f.hameconnage.enfant": T("Un faux message imite quelqu'un de confiance pour te voler un secret : on compare, on vérifie ailleurs, on ne donne rien.", "A fake message imitates someone you trust to steal a secret: compare, check elsewhere, give nothing.", "Un mensaje falso imita a alguien de confianza para robarte un secreto: compara, verifica en otro sitio, no des nada.", "Eine falsche Nachricht ahmt jemanden nach, dem du vertraust, um ein Geheimnis zu stehlen: vergleichen, anders prüfen, nichts geben.", "Un messaggio falso imita qualcuno di fiducia per rubarti un segreto: confronta, verifica altrove, non dare niente.", "Uma mensagem falsa imita alguém de confiança para roubar um segredo: compare, confira em outro lugar, não dê nada.", "Фальшивое сообщение притворяется кем-то знакомым, чтобы украсть секрет: сравни, проверь иначе, ничего не давай.", "假消息会冒充你信任的人来骗秘密：对比、换个渠道核实、什么都别给。", "ニセのメッセージは信頼できる人のふりをして秘密をぬすむ：くらべる、別の道で確かめる、何もわたさない。", "नकली संदेश भरोसेमंद की नकल करके राज़ चुराता है: मिलाओ, कहीं और जाँचो, कुछ मत दो।", "الرسالة المزيفة تقلّد شخصًا موثوقًا لتسرق سرًا: قارن، تحقق في مكان آخر، لا تعطِ شيئًا.", "নকল বার্তা ভরসার কারো ভান করে গোপন কথা চুরি করে: মেলাও, অন্যত্র যাচাই করো, কিছু দিও না।", "Pesan palsu meniru orang tepercaya untuk mencuri rahasia: bandingkan, periksa di tempat lain, jangan beri apa pun.", "جعلی پیغام کسی بھروسے والے کی نقل کر کے راز چراتا ہے: ملاؤ، کہیں اور جانچو، کچھ نہ دو۔"),
 "cit.f.hameconnage.grands": T("Hameçonnage (phishing) : urgence, demande de secret, lien ou expéditeur qui ne correspond pas. diff et grep http aident à repérer les écarts.", "Phishing: urgency, request for a secret, mismatched link or sender. diff and grep http help spot the differences.", "Phishing: urgencia, petición de secreto, enlace o remitente que no corresponde. diff y grep http ayudan a detectar diferencias.", "Phishing: Dringlichkeit, Bitte um Geheimnis, unpassender Link oder Absender. diff und grep http helfen, Abweichungen zu finden.", "Phishing: urgenza, richiesta di segreto, link o mittente che non corrisponde. diff e grep http aiutano a scovare le differenze.", "Phishing: urgência, pedido de segredo, link ou remetente que não bate. diff e grep http ajudam a achar as diferenças.", "Фишинг: срочность, просьба о секрете, несовпадающая ссылка или отправитель. diff и grep http помогают найти расхождения.", "网络钓鱼：催促、索要秘密、对不上的链接或寄件人。diff 和 grep http 能帮你找出差别。", "フィッシング：急がせる、秘密を聞く、合わないリンクや送り主。diff と grep http でちがいを見つけられる。", "फ़िशिंग: जल्दबाज़ी, राज़ की माँग, मेल न खाता लिंक या भेजने वाला। diff और grep http फ़र्क़ पकड़ने में मदद करते हैं।", "التصيّد: استعجال، طلب سر، رابط أو مرسل لا يتطابق. يساعد diff وgrep http على كشف الفروق.", "ফিশিং: তাড়াহুড়ো, গোপন কথা চাওয়া, না-মেলা লিংক বা প্রেরক। diff আর grep http পার্থক্য ধরতে সাহায্য করে।", "Phishing: desakan, permintaan rahasia, tautan atau pengirim yang tak cocok. diff dan grep http membantu menemukan perbedaan.", "فشنگ: جلدی، راز کی مانگ، نہ ملتا لنک یا بھیجنے والا۔ diff اور grep http فرق پکڑنے میں مدد کرتے ہیں۔"),
 "cit.f.hameconnage.limite": T("Une fausse lettre peut être parfaite (sans faute ni lien bizarre) : c'est la DEMANDE de secret qui trahit.", "A fake letter can be perfect (no typo, no weird link): it's the REQUEST for a secret that gives it away.", "Una carta falsa puede ser perfecta (sin faltas ni enlaces raros): es la PETICIÓN de secreto la que la delata.", "Ein falscher Brief kann perfekt sein (ohne Fehler, ohne seltsamen Link): Die BITTE um ein Geheimnis verrät ihn.", "Una lettera falsa può essere perfetta (senza errori né link strani): è la RICHIESTA di segreto che la tradisce.", "Uma carta falsa pode ser perfeita (sem erros nem link estranho): é o PEDIDO de segredo que a denuncia.", "Фальшивое письмо может быть безупречным (без ошибок и странных ссылок): выдаёт его ПРОСЬБА о секрете.", "假信也可能完美无缺（没错字、没怪链接）：露馅的是它“要秘密”。", "ニセの手紙は完ぺきなこともある（まちがいもへんなリンクもない）。ばれるのは秘密を「たのむ」ところ。", "नकली चिट्ठी बिल्कुल सही हो सकती है (बिना गलती, बिना अजीब लिंक): राज़ की माँग ही उसे पकड़वाती है।", "قد تكون الرسالة المزيفة مثالية (بلا أخطاء ولا رابط غريب): طلب السر هو ما يفضحها.", "নকল চিঠি নিখুঁত হতে পারে (ভুল বা অদ্ভুত লিংক ছাড়া): গোপন কথা চাওয়াটাই ধরিয়ে দেয়।", "Surat palsu bisa sempurna (tanpa salah ketik atau tautan aneh): PERMINTAAN rahasialah yang membongkarnya.", "جعلی خط بالکل درست ہو سکتا ہے (بغیر غلطی، بغیر عجیب لنک): راز کی مانگ ہی اسے پکڑواتی ہے۔"),
 "cit.f.hameconnage.idee": T("« Le cadenas du navigateur prouve que le site est honnête » : faux, il prouve seulement à qui tu parles.", "“The browser padlock proves the site is honest”: false, it only proves who you are talking to.", "«El candado del navegador prueba que el sitio es honesto»: falso, solo prueba con quién hablas.", "„Das Schloss im Browser beweist, dass die Seite ehrlich ist“: falsch, es beweist nur, mit wem du sprichst.", "«Il lucchetto del browser prova che il sito è onesto»: falso, prova solo con chi parli.", "«O cadeado do navegador prova que o site é honesto»: falso, só prova com quem você fala.", "«Замок в браузере доказывает честность сайта» — неверно, он лишь показывает, с кем ты говоришь.", "“浏览器上的小锁证明网站是正经的”：错，它只证明你在跟谁说话。", "「ブラウザの錠前はサイトが正直な証拠」：まちがい。だれと話しているかを示すだけ。", "«ब्राउज़र का ताला साबित करता है कि साइट ईमानदार है»: गलत, यह बस बताता है कि तुम किससे बात कर रहे हो।", "«قفل المتصفح يثبت أن الموقع نزيه»: خطأ، يثبت فقط مع من تتحدث.", "«ব্রাউজারের তালা প্রমাণ করে সাইট সৎ»: ভুল, শুধু প্রমাণ করে তুমি কার সাথে কথা বলছ।", "«Gembok di peramban membuktikan situsnya jujur»: salah, itu hanya membuktikan dengan siapa kamu bicara.", "«براؤزر کا تالا ثابت کرتا ہے کہ سائٹ ایمان دار ہے»: غلط، یہ صرف بتاتا ہے کہ تم کس سے بات کر رہے ہو۔"),
 # phrase de passe
 "cit.f.phrase_de_passe.enfant": T("Plusieurs mots tirés au hasard font un secret facile à retenir et très dur à deviner. Jamais ton vrai secret dans un jeu !", "Several randomly drawn words make a secret that's easy to remember and very hard to guess. Never your real secret in a game!", "Varias palabras al azar forman un secreto fácil de recordar y muy difícil de adivinar. ¡Nunca tu secreto real en un juego!", "Mehrere zufällige Wörter ergeben ein Geheimnis, leicht zu merken und schwer zu erraten. Nie dein echtes Geheimnis in einem Spiel!", "Più parole estratte a caso fanno un segreto facile da ricordare e difficile da indovinare. Mai il tuo vero segreto in un gioco!", "Várias palavras sorteadas formam um segredo fácil de lembrar e muito difícil de adivinhar. Nunca seu segredo real num jogo!", "Несколько случайных слов — секрет, который легко запомнить и трудно угадать. Никогда не вводи настоящий секрет в игре!", "几个随机抽的词，组成好记又难猜的秘密。千万别在游戏里用你的真秘密！", "でたらめに選んだ言葉をいくつかつなげると、おぼえやすく当てにくい秘密になる。本物の秘密はゲームに入れない！", "कुछ रैंडम शब्द मिलकर याद रखने में आसान, अंदाज़ा लगाने में कठिन राज़ बनाते हैं। खेल में कभी असली राज़ नहीं!", "عدة كلمات عشوائية تصنع سرًا سهل الحفظ صعب التخمين. لا تضع سرك الحقيقي في لعبة أبدًا!", "কয়েকটা এলোমেলো শব্দ মিলে মনে রাখা সহজ, আন্দাজ করা কঠিন গোপন কথা হয়। খেলায় কখনো আসল গোপন কথা নয়!", "Beberapa kata acak membentuk rahasia yang mudah diingat dan sulit ditebak. Jangan pernah rahasia aslimu di permainan!", "چند بے ترتیب لفظ مل کر یاد رکھنے میں آسان، اندازہ لگانے میں مشکل راز بناتے ہیں۔ کھیل میں کبھی اصل راز نہیں!"),
 "cit.f.phrase_de_passe.grands": T("Entropie = mots × log2(taille de la liste) : 6 mots parmi 7776 (Diceware) ≈ 77 bits. La longueur compte plus que la complexité (NIST SP 800-63B).", "Entropy = words × log2(list size): 6 words from 7776 (Diceware) ≈ 77 bits. Length matters more than complexity (NIST SP 800-63B).", "Entropía = palabras × log2(tamaño de la lista): 6 palabras de 7776 (Diceware) ≈ 77 bits. La longitud importa más que la complejidad (NIST SP 800-63B).", "Entropie = Wörter × log2(Listengröße): 6 Wörter aus 7776 (Diceware) ≈ 77 Bit. Länge zählt mehr als Komplexität (NIST SP 800-63B).", "Entropia = parole × log2(dimensione lista): 6 parole su 7776 (Diceware) ≈ 77 bit. La lunghezza conta più della complessità (NIST SP 800-63B).", "Entropia = palavras × log2(tamanho da lista): 6 palavras de 7776 (Diceware) ≈ 77 bits. O tamanho importa mais que a complexidade (NIST SP 800-63B).", "Энтропия = слова × log2(размер списка): 6 слов из 7776 (Diceware) ≈ 77 бит. Длина важнее сложности (NIST SP 800-63B).", "熵 = 词数 × log2（词表大小）：从 7776 个词（Diceware）里选 6 个 ≈ 77 比特。长度比复杂度更重要（NIST SP 800-63B）。", "エントロピー＝語数 × log2（リストの大きさ）：7776語（Diceware）から6語 ≈ 77 ビット。長さはややこしさより大事（NIST SP 800-63B）。", "एन्ट्रॉपी = शब्द × log2(सूची का आकार): 7776 में से 6 शब्द (Diceware) ≈ 77 बिट। लंबाई जटिलता से ज़्यादा मायने रखती है (NIST SP 800-63B)।", "الإنتروبيا = الكلمات × log2(حجم القائمة): 6 كلمات من 7776 (Diceware) ≈ 77 بت. الطول أهم من التعقيد (NIST SP 800-63B).", "এনট্রপি = শব্দ × log2(তালিকার আকার): ৭৭৭৬টার মধ্যে ৬টা শব্দ (Diceware) ≈ ৭৭ বিট। জটিলতার চেয়ে দৈর্ঘ্য বেশি জরুরি (NIST SP 800-63B)।", "Entropi = kata × log2(ukuran daftar): 6 kata dari 7776 (Diceware) ≈ 77 bit. Panjang lebih penting dari kerumitan (NIST SP 800-63B).", "اینٹروپی = لفظ × log2(فہرست کا سائز): 7776 میں سے 6 لفظ (Diceware) ≈ 77 بٹ۔ لمبائی پیچیدگی سے زیادہ اہم ہے (NIST SP 800-63B)۔"),
 "cit.f.phrase_de_passe.limite": T("Le calcul ne vaut que si les mots sont VRAIMENT tirés au hasard ; une phrase connue (une chanson) tombe tout de suite.", "The calculation only holds if the words are TRULY random; a known phrase (a song) falls immediately.", "El cálculo solo vale si las palabras son REALMENTE al azar; una frase conocida (una canción) cae enseguida.", "Die Rechnung gilt nur bei WIRKLICH zufälligen Wörtern; ein bekannter Satz (ein Lied) fällt sofort.", "Il calcolo vale solo se le parole sono DAVVERO casuali; una frase nota (una canzone) cade subito.", "A conta só vale se as palavras forem MESMO sorteadas; uma frase conhecida (uma música) cai na hora.", "Расчёт верен, только если слова ДЕЙСТВИТЕЛЬНО случайны; известная фраза (песня) падает сразу.", "这个算法只在词真的是随机抽的时候才成立；有名的句子（歌词）一下子就被猜中。", "この計算は、言葉が本当にでたらめに選ばれたときだけ正しい。よく知られた文（歌）はすぐ破られる。", "हिसाब तभी सही है जब शब्द सच में रैंडम हों; जाना-पहचाना वाक्य (गाना) तुरंत टूटता है।", "يصح الحساب فقط إذا كانت الكلمات عشوائية حقًا؛ والعبارة المعروفة (أغنية) تسقط فورًا.", "হিসাব তখনই ঠিক যখন শব্দ সত্যিই এলোমেলো; পরিচিত বাক্য (গান) সাথে সাথে ভাঙে।", "Hitungan hanya berlaku bila kata-katanya BENAR-BENAR acak; kalimat terkenal (lagu) langsung jebol.", "حساب تب ہی درست ہے جب لفظ واقعی بے ترتیب ہوں؛ مشہور جملہ (گانا) فوراً ٹوٹتا ہے۔"),
 "cit.f.phrase_de_passe.idee": T("« Un mot de passe court avec des symboles est plus sûr » : faux, la longueur gagne.", "“A short password with symbols is safer”: false, length wins.", "«Una contraseña corta con símbolos es más segura»: falso, gana la longitud.", "„Ein kurzes Passwort mit Sonderzeichen ist sicherer“: falsch, Länge gewinnt.", "«Una password corta con simboli è più sicura»: falso, vince la lunghezza.", "«Uma senha curta com símbolos é mais segura»: falso, o tamanho ganha.", "«Короткий пароль с символами надёжнее» — неверно, побеждает длина.", "“短而带符号的密码更安全”：错，长度才赢。", "「短くて記号入りのパスワードのほうが安全」：まちがい。長さが勝つ。", "«चिह्नों वाला छोटा पासवर्ड ज़्यादा सुरक्षित»: गलत, लंबाई जीतती है।", "«كلمة مرور قصيرة برموز أكثر أمانًا»: خطأ، الطول يفوز.", "«চিহ্নসহ ছোট পাসওয়ার্ড বেশি নিরাপদ»: ভুল, দৈর্ঘ্য জেতে।", "«Kata sandi pendek bersimbol lebih aman»: salah, panjang yang menang.", "«نشانوں والا چھوٹا پاس ورڈ زیادہ محفوظ»: غلط، لمبائی جیتتی ہے۔"),
 # boîtes
 "cit.f.boites.enfant": T("Une boîte est un petit monde-piège du jeu : on y trouve la faiblesse, puis on la répare.", "A box is a little trap-world made by the game: you find the weakness, then you fix it.", "Una caja es un pequeño mundo-trampa del juego: encuentras la debilidad y luego la reparas.", "Eine Kiste ist eine kleine Fallenwelt des Spiels: Schwachstelle finden, dann beheben.", "Una scatola è un piccolo mondo-trappola del gioco: trovi la debolezza, poi la ripari.", "Uma caixa é um pequeno mundo-armadilha do jogo: você acha a falha e depois conserta.", "Коробка — маленький мир-ловушка игры: находишь слабое место и чинишь его.", "盒子是游戏做的陷阱小世界：先找出弱点，再把它修好。", "ボックスはゲームが作ったわなの小世界：弱点を見つけて、直す。", "बक्सा खेल की छोटी जाल-दुनिया है: कमज़ोरी ढूँढो, फिर ठीक करो।", "الصندوق عالم-فخ صغير صنعته اللعبة: تجد الثغرة ثم تصلحها.", "বাক্স হলো খেলার ছোট্ট ফাঁদ-জগৎ: দুর্বলতা খোঁজো, তারপর সারাও।", "Kotak adalah dunia-jebakan kecil buatan permainan: temukan kelemahan, lalu perbaiki.", "ڈبہ کھیل کی چھوٹی جال دنیا ہے: کمزوری ڈھونڈو، پھر ٹھیک کرو۔"),
 "cit.f.boites.grands": T("Inspiré de Root-Me et Hack The Box, mais entièrement simulé dans ton terrain : énumérer (ls -la, find -perm, grep -r), puis corriger (chmod, effacer, rotation).", "Inspired by Root-Me and Hack The Box, but fully simulated in your playground: enumerate (ls -la, find -perm, grep -r), then fix (chmod, erase, rotate).", "Inspirado en Root-Me y Hack The Box, pero totalmente simulado en tu terreno: enumerar (ls -la, find -perm, grep -r) y corregir (chmod, borrar, rotar).", "Inspiriert von Root-Me und Hack The Box, aber ganz simuliert in deinem Gelände: aufzählen (ls -la, find -perm, grep -r), dann beheben (chmod, löschen, rotieren).", "Ispirato a Root-Me e Hack The Box, ma tutto simulato nel tuo terreno: enumerare (ls -la, find -perm, grep -r), poi correggere (chmod, cancellare, ruotare).", "Inspirado no Root-Me e no Hack The Box, mas todo simulado no seu terreno: enumerar (ls -la, find -perm, grep -r) e corrigir (chmod, apagar, rotacionar).", "По мотивам Root-Me и Hack The Box, но целиком в симуляции на твоём участке: перечислить (ls -la, find -perm, grep -r), затем исправить (chmod, удалить, сменить).", "灵感来自 Root-Me 和 Hack The Box，但完全在你的场地里模拟：先枚举（ls -la、find -perm、grep -r），再修复（chmod、删除、轮换）。", "Root-Me や Hack The Box がもとだが、きみの遊び場の中だけでまねしたもの：列挙（ls -la、find -perm、grep -r）して、直す（chmod、消す、ローテーション）。", "Root-Me और Hack The Box से प्रेरित, पर पूरी तरह तुम्हारे मैदान में नकली: गिनो (ls -la, find -perm, grep -r), फिर सुधारो (chmod, मिटाओ, रोटेशन)।", "مستوحى من Root-Me وHack The Box لكنه محاكى بالكامل في ساحتك: عدّد (ls -la، find -perm، grep -r) ثم أصلح (chmod، المحو، التدوير).", "Root-Me আর Hack The Box থেকে অনুপ্রাণিত, কিন্তু পুরোটাই তোমার মাঠে নকল: গণনা (ls -la, find -perm, grep -r), তারপর সারানো (chmod, মোছা, রোটেশন)।", "Terinspirasi Root-Me dan Hack The Box, tapi seluruhnya disimulasikan di lahanmu: enumerasi (ls -la, find -perm, grep -r), lalu perbaiki (chmod, hapus, rotasi).", "Root-Me اور Hack The Box سے متاثر، مگر پوری طرح تمہارے میدان میں نقلی: شمار (ls -la، find -perm، grep -r)، پھر درست کرو (chmod، مٹاؤ، روٹیشن)۔"),
 "cit.f.boites.limite": T("Les boîtes du jeu sont faciles et bien rangées ; un vrai système est bien plus grand, et on n'y touche jamais sans autorisation.", "The game's boxes are easy and tidy; a real system is much bigger, and you never touch it without permission.", "Las cajas del juego son fáciles y ordenadas; un sistema real es mucho mayor y nunca se toca sin permiso.", "Die Kisten des Spiels sind leicht und ordentlich; ein echtes System ist viel größer, und man rührt es nie ohne Erlaubnis an.", "Le scatole del gioco sono facili e ordinate; un vero sistema è molto più grande e non si tocca mai senza permesso.", "As caixas do jogo são fáceis e arrumadas; um sistema real é muito maior e nunca se mexe sem permissão.", "Коробки игры простые и аккуратные; настоящая система куда больше, и её никогда не трогают без разрешения.", "游戏里的盒子简单又整齐；真的系统大得多，没得到允许绝不能碰。", "ゲームのボックスはかんたんで整っている。本物のシステムはずっと大きく、許可なしには決してさわらない。", "खेल के बक्से आसान और सुव्यवस्थित हैं; असली सिस्टम कहीं बड़ा होता है, और बिना अनुमति उसे कभी नहीं छूते।", "صناديق اللعبة سهلة ومرتبة؛ النظام الحقيقي أكبر بكثير ولا يُمس دون إذن أبدًا.", "খেলার বাক্স সহজ আর গোছানো; আসল সিস্টেম অনেক বড়, আর অনুমতি ছাড়া কখনো ছোঁয়া হয় না।", "Kotak permainan mudah dan rapi; sistem sungguhan jauh lebih besar, dan tak pernah disentuh tanpa izin.", "کھیل کے ڈبے آسان اور ترتیب والے ہیں؛ اصل سسٹم کہیں بڑا ہوتا ہے، اور بغیر اجازت اسے کبھی نہیں چھوتے۔"),
 "cit.f.boites.idee": T("« Si je sais trouver une faille, j'ai le droit d'essayer partout » : faux, c'est interdit par la loi hors de ce qui t'appartient.", "“If I can find a flaw, I'm allowed to try anywhere”: false, the law forbids it outside what belongs to you.", "«Si sé encontrar un fallo, puedo probar en cualquier sitio»: falso, la ley lo prohíbe fuera de lo que es tuyo.", "„Wenn ich eine Lücke finde, darf ich es überall versuchen“: falsch, das Gesetz verbietet es außerhalb deines Eigentums.", "«Se so trovare una falla, posso provare ovunque»: falso, la legge lo vieta fuori da ciò che ti appartiene.", "«Se sei achar uma falha, posso tentar em qualquer lugar»: falso, a lei proíbe fora do que é seu.", "«Если я умею находить уязвимости, мне можно пробовать где угодно» — неверно: закон запрещает это вне твоего собственного.", "“我会找漏洞，就可以到处试”：错，在不属于你的地方这样做是违法的。", "「すきまを見つけられるなら、どこでもためしていい」：まちがい。自分のもの以外では法律で禁止されている。", "«कमज़ोरी ढूँढना आता है तो हर जगह आज़मा सकता हूँ»: गलत, अपनी चीज़ों के बाहर क़ानून मना करता है।", "«إن كنت أعرف إيجاد ثغرة فيحق لي التجربة في كل مكان»: خطأ، القانون يمنعه خارج ما يخصك.", "«ফাঁক খুঁজতে পারলে সব জায়গায় চেষ্টা করতে পারি»: ভুল, নিজের জিনিসের বাইরে আইন নিষেধ করে।", "«Kalau bisa menemukan celah, boleh mencoba di mana saja»: salah, hukum melarangnya di luar milikmu.", "«کمزوری ڈھونڈنا آتا ہے تو ہر جگہ آزما سکتا ہوں»: غلط، اپنی چیزوں کے باہر قانون منع کرتا ہے۔"),
 # pare-feu
 "cit.f.pare_feu.enfant": T("Un pare-feu, c'est la liste des portes qu'on laisse ouvertes, et pour qui.", "A firewall is the list of doors you leave open, and for whom.", "Un cortafuegos es la lista de puertas que dejas abiertas, y para quién.", "Eine Firewall ist die Liste der Türen, die offen bleiben, und für wen.", "Un firewall è la lista delle porte che lasci aperte, e per chi.", "Um firewall é a lista das portas que ficam abertas, e para quem.", "Межсетевой экран — список дверей, которые оставляешь открытыми, и для кого.", "防火墙就是一张清单：哪些门开着、对谁开。", "ファイアウォールは、どの扉をだれのために開けておくかのリスト。", "फ़ायरवॉल यानी कौन-से दरवाज़े खुले रहें और किसके लिए, इसकी सूची।", "الجدار الناري قائمة الأبواب التي تتركها مفتوحة، ولمن.", "ফায়ারওয়াল মানে কোন দরজা খোলা থাকবে আর কার জন্য, তার তালিকা।", "Firewall adalah daftar pintu yang dibiarkan terbuka, dan untuk siapa.", "فائر وال یعنی کون سے دروازے کھلے رہیں اور کس کے لیے، اس کی فہرست۔"),
 "cit.f.pare_feu.grands": T("ss -tln montre ce qui écoute ; le pare-feu (nftables, firewalld) filtre qui peut y arriver. Moins de services ouverts = moins de surface d'attaque.", "ss -tln shows what is listening; the firewall (nftables, firewalld) filters who can reach it. Fewer open services = smaller attack surface.", "ss -tln muestra lo que escucha; el cortafuegos (nftables, firewalld) filtra quién llega. Menos servicios abiertos = menos superficie de ataque.", "ss -tln zeigt, was lauscht; die Firewall (nftables, firewalld) filtert, wer hinkommt. Weniger offene Dienste = kleinere Angriffsfläche.", "ss -tln mostra cosa è in ascolto; il firewall (nftables, firewalld) filtra chi può arrivarci. Meno servizi aperti = meno superficie d'attacco.", "ss -tln mostra o que escuta; o firewall (nftables, firewalld) filtra quem chega. Menos serviços abertos = menor superfície de ataque.", "ss -tln показывает, что слушает; экран (nftables, firewalld) фильтрует, кто туда доберётся. Меньше открытых служб — меньше поверхность атаки.", "ss -tln 显示谁在监听；防火墙（nftables、firewalld）过滤谁能到达。开的服务越少，被攻击的面就越小。", "ss -tln は待ち受けているものを表示し、ファイアウォール（nftables、firewalld）はだれが届くかをしぼる。開いたサービスが少ないほど、ねらわれる面がへる。", "ss -tln दिखाता है क्या सुन रहा है; फ़ायरवॉल (nftables, firewalld) छाँटता है कौन पहुँचे। कम खुली सेवाएँ = कम हमले की जगह।", "يعرض ss -tln ما يستمع؛ ويصفّي الجدار الناري (nftables، firewalld) من يصل. خدمات مفتوحة أقل = سطح هجوم أصغر.", "ss -tln দেখায় কী শুনছে; ফায়ারওয়াল (nftables, firewalld) ছাঁকে কে পৌঁছাবে। কম খোলা সেবা = কম আক্রমণের জায়গা।", "ss -tln menampilkan yang mendengarkan; firewall (nftables, firewalld) menyaring siapa yang bisa sampai. Lebih sedikit layanan terbuka = permukaan serangan lebih kecil.", "ss -tln دکھاتا ہے کیا سن رہا ہے؛ فائر وال (nftables، firewalld) چھانتا ہے کون پہنچے۔ کم کھلی سروسز = کم حملے کی جگہ۔"),
 "cit.f.pare_feu.limite": T("Un pare-feu ne protège pas d'un piège qu'on lance soi-même, ni d'un mot de passe donné à un faux facteur.", "A firewall doesn't protect against a trap you run yourself, nor a password given to a fake mail carrier.", "Un cortafuegos no protege de una trampa que ejecutas tú mismo, ni de una contraseña dada a un falso cartero.", "Eine Firewall schützt nicht vor einer selbst gestarteten Falle oder einem Passwort für einen falschen Briefträger.", "Un firewall non protegge da una trappola che lanci tu stesso, né da una password data a un falso postino.", "Um firewall não protege de uma armadilha que você mesmo roda, nem de uma senha dada a um falso carteiro.", "Экран не защитит от ловушки, которую ты запустил сам, и от пароля, отданного фальшивому почтальону.", "防火墙挡不住你自己运行的陷阱，也挡不住你交给假邮差的密码。", "ファイアウォールは、自分で実行したわなも、ニセ郵便屋さんにわたしたパスワードも防げない。", "फ़ायरवॉल खुद चलाए जाल से नहीं बचाता, न नकली डाकिए को दिए पासवर्ड से।", "لا يحمي الجدار الناري من فخ تشغّله بنفسك، ولا من كلمة مرور أعطيتها لساعي بريد مزيف.", "ফায়ারওয়াল নিজে চালানো ফাঁদ থেকে বা নকল ডাকপিয়নকে দেওয়া পাসওয়ার্ড থেকে বাঁচায় না।", "Firewall tak melindungi dari jebakan yang kamu jalankan sendiri, atau kata sandi yang diberikan ke tukang pos palsu.", "فائر وال خود چلائے جال سے نہیں بچاتا، نہ جعلی ڈاکیے کو دیے پاس ورڈ سے۔"),
 "cit.f.pare_feu.idee": T("« Avec un pare-feu, je suis protégé de tout » : faux, c'est une couche parmi d'autres.", "“With a firewall I'm protected from everything”: false, it's one layer among many.", "«Con un cortafuegos estoy protegido de todo»: falso, es una capa entre otras.", "„Mit Firewall bin ich vor allem geschützt“: falsch, sie ist eine Schicht unter vielen.", "«Con un firewall sono protetto da tutto»: falso, è uno strato tra tanti.", "«Com firewall estou protegido de tudo»: falso, é uma camada entre outras.", "«С экраном я защищён от всего» — неверно, это лишь один слой из многих.", "“有防火墙就什么都防住了”：错，它只是很多层里的一层。", "「ファイアウォールがあれば何でも防げる」：まちがい。たくさんある層のひとつ。", "«फ़ायरवॉल है तो हर चीज़ से सुरक्षित»: गलत, यह कई परतों में से एक है।", "«بالجدار الناري أنا محمي من كل شيء»: خطأ، إنه طبقة بين طبقات.", "«ফায়ারওয়াল থাকলে সবকিছু থেকে সুরক্ষিত»: ভুল, এটা অনেক স্তরের একটা।", "«Dengan firewall aku terlindung dari segalanya»: salah, itu satu lapisan di antara banyak.", "«فائر وال ہے تو ہر چیز سے محفوظ»: غلط، یہ کئی تہوں میں سے ایک ہے۔"),
}
